'use server'

import { createClient } from '@/utils/supabase/server'
import { createClient as createAdminClient } from '@supabase/supabase-js'

type EmailType = 'greensheet' | 'alert' | 'summary'

interface EmailPayload {
  recipients: string[];
  subject: string;
  htmlContent: string;
}

// Helper to get the Admin Client (for fetching emails)
const getAdmin = () => createAdminClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
)

// --- CORE DISPATCHER ---
export async function dispatchEmail(type: EmailType, payload: EmailPayload) {
  const supabase = createClient() // Standard client for auth check
  const { data: { session } } = await supabase.auth.getSession()

  // 1. Check Settings
  let settingKey = ''
  if (type === 'greensheet') settingKey = 'enable_email_blasts'
  if (type === 'alert') settingKey = 'enable_alert_ed' // Generic bucket for now
  
  if (settingKey) {
      const { data: setting } = await supabase.from('system_settings').select('value').eq('key', settingKey).single()
      if (setting && setting.value === false) return { success: false, reason: 'Disabled' }
  }

  // 2. Send via Edge Function
  const response = await fetch(`${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/send-email`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${session?.access_token || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY}`
    },
    body: JSON.stringify({ type, ...payload })
  })

  if (!response.ok) {
      const err = await response.text()
      console.error("Email Dispatch Failed:", err)
      return { success: false, error: err }
  }

  return { success: true }
}

// --- TRIGGER 1: GREEN SHEET (Faculty Only) ---
export async function triggerGreenSheetBlast() {
  const supabase = createClient()
  const admin = getAdmin()

  // 1. Get Content
  const { data: html } = await supabase.rpc('generate_daily_email_html')
  if (!html) return { error: "Failed to generate HTML" }

  // 2. Get Faculty IDs
  const { data: facultyIds } = await supabase.rpc('get_faculty_user_ids')
  if (!facultyIds || facultyIds.length === 0) return { error: "No faculty found" }

  // 3. Map to Emails (using Admin)
  const { data: users } = await admin.auth.admin.listUsers()
  const facultyEmails = users.users
    .filter(u => facultyIds.some((f: any) => f.id === u.id))
    .map(u => u.email!)
    .filter(Boolean)

  if (facultyEmails.length === 0) return { error: "No faculty emails found" }

  return dispatchEmail('greensheet', {
    recipients: facultyEmails,
    subject: `Daily Report - ${new Date().toLocaleDateString()}`,
    htmlContent: html
  })
}

// --- TRIGGER 2: TOUR SHEET ALERT (Debtors Only) ---
export async function triggerTourSheetAlert() {
  const supabase = createClient()
  const admin = getAdmin()

  // 1. Get Debtors
  const { data: debtors } = await supabase.rpc('get_tour_sheet_debtors') // returns { id, balance }
  if (!debtors || debtors.length === 0) return { success: true, message: "No one on the tour sheet." }

  // 2. Map to Emails
  const { data: users } = await admin.auth.admin.listUsers()
  
  // We send INDIVIDUAL emails here to preserve privacy
  let sentCount = 0;
  
  for (const debtor of debtors) {
      const user = users.users.find(u => u.id === debtor.id)
      if (user?.email) {
          await dispatchEmail('alert', {
              recipients: [user.email],
              subject: `Action Required: You are on the Tour Sheet`,
              htmlContent: `
                <h3>Tour Sheet Notification</h3>
                <p>You currently have a balance of <strong>${debtor.balance} Tours</strong>.</p>
                <p>You are required to march until this balance is cleared.</p>
              `
          })
          sentCount++
      }
  }

  return { success: true, sent: sentCount }
}

// --- TRIGGER 3: ACTION ITEMS (Pending Work) ---
export async function triggerActionItemAlert() {
  const supabase = createClient()
  const admin = getAdmin()

  const { data: activeUsers } = await supabase.rpc('get_users_with_pending_actions')
  if (!activeUsers || activeUsers.length === 0) return { success: true, message: "No pending actions." }

  const { data: users } = await admin.auth.admin.listUsers()
  let sentCount = 0;

  for (const record of activeUsers) {
      const user = users.users.find(u => u.id === record.user_id)
      if (user?.email) {
          const items = []
          if (record.approval_count > 0) items.push(`${record.approval_count} reports to approve`)
          if (record.revision_count > 0) items.push(`${record.revision_count} reports returned for revision`)
          if (record.appeal_count > 0) items.push(`${record.appeal_count} appeal updates`)

          await dispatchEmail('alert', {
              recipients: [user.email],
              subject: `CadetFlow: You have ${record.approval_count + record.revision_count + record.appeal_count} Action Items`,
              htmlContent: `
                <h3>Action Required</h3>
                <p>You have pending items in your CadetFlow dashboard:</p>
                <ul>${items.map(i => `<li>${i}</li>`).join('')}</ul>
                <p><a href="${process.env.NEXT_PUBLIC_SITE_URL}">Go to Dashboard</a></p>
              `
          })
          sentCount++
      }
  }

  return { success: true, sent: sentCount }
}